import {ADVENTURE_PACKS} from './adventure-content.js';
import {DRAFT_PACKS} from './draft-content.js';
import {mountAdventure} from './adventure-ui.js';
import {mountDraft} from './draft-ui.js';
import {validatePlayableContent,GAME_TEMPLATES,gameReviewHTML} from './content-registry.js';
import {ResourceWorkshop} from '../resource-workshop.js';
import './mode-style.css';
const root=document.querySelector('#game-library'),layer=document.querySelector('#library-layer');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let assets={},active=null,custom=[],notice='',modal=null,returnFocus=null;
const storageKey='mosaic:reviewed-games:v1';
function readCustom(){try{const data=JSON.parse(localStorage.getItem(storageKey)||'[]');if(!Array.isArray(data)||data.length>20)throw Error();custom=data.map(validatePlayableContent).filter(p=>p.template!=='underlight-v1')}catch{notice='Saved imported games could not be read. The included adventures are ready to play.';custom=[]}}
function allPacks(){return [...new Map([...ADVENTURE_PACKS,...DRAFT_PACKS,...custom].map(pack=>[pack.id,pack])).values()]}
function register(pack){const clean=validatePlayableContent(pack);if(clean.template==='underlight-v1')throw Error('Open this chapter through the RPG.');custom=custom.filter(p=>p.id!==clean.id);custom.unshift(clean);custom=custom.slice(0,20);try{localStorage.setItem(storageKey,JSON.stringify(custom))}catch{notice='This browser cannot save more games. You can play now and export your game for later.'}return clean}
function destroy(){active?.destroy();active=null;root.innerHTML=''}
function closeModal(){modal=null;layer.innerHTML='';layer.hidden=true;returnFocus?.focus?.()}
const button=(text,action,attrs='',kind='')=>`<button type="button" data-act="${action}" ${attrs} class="${kind}">${text}</button>`;
function wrap(html){return `<div class="scrim"><section class="panel" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button type="button" class="modal-close" data-act="close" aria-label="Close dialog">×</button>${html}</section></div>`}
function renderModal(){const focusId=layer.contains(document.activeElement)?document.activeElement.id:null;if(!modal){closeModal();return}layer.hidden=false;if(modal.kind==='import-review'){layer.innerHTML=wrap(`<p>Review imported game</p>${[...ADVENTURE_PACKS,...DRAFT_PACKS].some(p=>p.id===modal.draft.id)?'<p class="workshop-notice">This file will become this browser’s version of the included story with the same ID.</p>':''}<h2 id="modal-title">${esc(modal.draft.title)}</h2><p>${esc(modal.draft.hook)}</p>${gameReviewHTML(modal.draft,esc)}<label class="workshop-check"><input id="import-confirm" type="checkbox" ${modal.confirmed?'checked':''}>I checked the learning content and its sources.</label><div class="row">${button('Play reviewed game','import-use',modal.confirmed?'':'disabled','primary')}${button('Back to games','close')}</div>`)}else{layer.innerHTML=workshop.panel(modal,{esc,button,wrap})||wrap('<h2 id="modal-title">Open the RPG to use this chapter</h2><a href="/">Return to Lanternbound</a>')}if(focusId)layer.querySelector('#'+CSS.escape(focusId))?.focus(); }
function openModal(m){if(!modal)returnFocus=document.activeElement;modal=m;renderModal();layer.querySelector('h2')?.setAttribute('tabindex','-1');layer.querySelector('h2')?.focus()}
const context={get:()=>({pack:{id:'mosaic-games'},get modal(){return modal},openModal,renderModal}),download(data,name){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}};
const workshop=new ResourceWorkshop(context,{template:'adventure-v1',templates:['adventure-v1','draft-v1'],onActivate:async draft=>{start(register(draft))}});
function library(template='adventure-v1'){workshop.template=template;void workshop.open()}
function poster(template,title,desc,image){const packs=allPacks().filter(p=>p.template===template);return `<article class="game-poster ${template==='draft-v1'?'draft-poster':''}"><div class="poster-art" style="background-image:url('${esc(image)}')"><span class="poster-type">${template==='draft-v1'?'A strategy draft':'A 2D adventure'}</span><h2>${title}</h2></div><div class="poster-content"><p>${desc}</p><label for="choose-${template}">Choose a story</label><select id="choose-${template}">${packs.map(p=>`<option value="${esc(p.id)}">${esc(p.title)}</option>`).join('')}</select><div class="poster-actions"><button class="primary" data-play="${template}">Play</button><button data-create="${template}">Create from your material</button></div></div></article>`}
function hub(){destroy();closeModal();window.scrollTo({top:0,left:0,behavior:'instant'});history.replaceState(null,'','/modes.html');root.innerHTML=`<header class="library-heading"><a href="/" class="library-brand">✦ Lanternbound</a><nav aria-label="Game library"><a href="/">Return to the RPG</a><button data-library>Resource library</button></nav></header><section class="library-intro"><h1>A new way into every subject.</h1><p>Follow a story. Make a choice. Find out why it matters.</p></section><div class="game-posters">${poster('adventure-v1','The Thread Atlas','Step into an illustrated world. Read its clues, talk to its keepers and put your discoveries to work.',assets.rooms?.workshop)}${poster('draft-v1','Turning Points','Build a set of five choices. Discover how they work together when the world changes around them.',assets.tables?.draft||assets.rooms?.archive)}</div><section class="library-foot"><div><h2>Your material, a different adventure.</h2><p>Upload and review a source, choose a game format, then inspect what Muse Wonder creates. Included examples can be played immediately.</p></div><div class="library-file"><label for="game-import">Import a reviewed game file</label><input type="file" id="game-import" accept=".json,application/json"><p class="library-notice" role="status">${esc(notice)}</p></div></section>`;root.querySelectorAll('[data-play]').forEach(b=>b.addEventListener('click',()=>{const id=root.querySelector('#choose-'+b.dataset.play).value;const pack=allPacks().find(p=>p.id===id&&p.template===b.dataset.play);if(pack)start(pack)}));root.querySelectorAll('[data-create]').forEach(b=>b.addEventListener('click',()=>library(b.dataset.create)));root.querySelector('[data-library]').addEventListener('click',()=>library());root.querySelector('#game-import').addEventListener('change',async e=>{try{const f=e.target.files?.[0];if(!f)return;if(f.size>131072)throw Error('Choose a JSON game file below 128 KB.');const draft=validatePlayableContent(await f.text());if(draft.template==='underlight-v1')throw Error('Import this 3D chapter through the RPG Chapter workshop.');openModal({kind:'import-review',draft})}catch(err){notice=err.message;hub()}})}
function start(pack){const clean=validatePlayableContent(pack);if(clean.template==='underlight-v1')throw Error('This chapter belongs in the 3D RPG.');destroy();closeModal();history.replaceState(null,'','/modes.html?game='+encodeURIComponent(clean.id));const mount=clean.template==='draft-v1'?mountDraft:mountAdventure;active=mount(root,{pack:clean,assets,onExit:hub,onLibrary:()=>library(clean.template)});root.focus({preventScroll:true});window.scrollTo({top:0,left:0,behavior:'instant'})}
layer.addEventListener('click',async e=>{const b=e.target.closest('button[data-act]');if(!b||b.disabled)return;const action=b.dataset.act;try{if(action==='close'){closeModal();return}if(action==='import-use'&&modal?.confirmed){start(register(modal.draft));return}await workshop.act(action,b)}catch(err){if(modal){modal.feedback=err.message;renderModal()}}});
for(const type of ['input','change'])layer.addEventListener(type,async e=>{if(type==='input'&&e.target.type==='file')return;if(e.target.id==='import-confirm'){modal.confirmed=e.target.checked;renderModal();return}await workshop.change(e)});
document.addEventListener('keydown',e=>{if(!modal)return;if(e.key==='Escape'){e.preventDefault();closeModal();return}if(e.key==='Tab'){const nodes=[...layer.querySelectorAll('button:not(:disabled),a,input:not(:disabled),select,textarea,summary')].filter(n=>n.getClientRects().length);if(!nodes.length)return;const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&(document.activeElement===first||!layer.contains(document.activeElement))){e.preventDefault();last.focus()}else if(!e.shiftKey&&(document.activeElement===last||!layer.contains(document.activeElement))){e.preventDefault();first.focus()}}});
async function boot(){try{const response=await fetch('/game-modes/art/manifest.json');if(!response.ok)throw Error('The illustrated asset library did not load. Please reload.');assets=await response.json();readCustom();const params=new URLSearchParams(location.search),job=params.get('job'),id=params.get('game');if(job){const data=await workshop.request('jobs/'+encodeURIComponent(job));if(data.job.status!=='published')throw Error('Review this generated game in the Resource Library before playing.');start(register(data.job.draft))}else{const found=allPacks().find(p=>p.id===id);found?start(found):hub()}}catch(e){root.innerHTML=`<section class="library-error"><h1>One moment…</h1><p>${esc(e.message)}</p><button id="retry-library">Try again</button><a href="/">Return to the RPG</a></section>`;root.querySelector('#retry-library').addEventListener('click',()=>location.reload())}}
boot();
